-- ============================================================
-- Планограммы: бизнес-процессы модуля
--
-- Схемы хранятся в формате draw.io (mxGraph XML): один и тот же документ
-- открывается в diagrams.net и рисуется собственным просмотрщиком в бэк-офисе.
-- Гиперссылки узлов — штатные для draw.io <UserObject link="...">, поэтому
-- клик по квадрату или ромбу ведёт в соответствующий раздел модуля.
--
-- ФАЙЛ СГЕНЕРИРОВАН: scripts/gen_plg_processes.py — правки вносить там.
-- Префикс объектов: PLG_
-- ============================================================

CREATE SEQUENCE PLG_PROCESSES_SEQ START WITH 1 INCREMENT BY 1 NOCACHE;

CREATE TABLE PLG_PROCESSES (
  ID          NUMBER        NOT NULL,
  CODE        VARCHAR2(40)  NOT NULL,
  NAME_RU     VARCHAR2(200) NOT NULL,
  NAME_RO     VARCHAR2(200),
  NAME_EN     VARCHAR2(200),
  DESCR_RU    VARCHAR2(2000),
  DESCR_RO    VARCHAR2(2000),
  DESCR_EN    VARCHAR2(2000),
  DIAGRAM_XML CLOB,                       -- mxGraph XML (формат draw.io)
  NODE_COUNT  NUMBER        DEFAULT 0,
  SORT_ORDER  NUMBER        DEFAULT 0,
  STATUS      VARCHAR2(20)  DEFAULT 'active',
  UPDATED_BY  VARCHAR2(150),
  CREATED_AT  TIMESTAMP     DEFAULT SYSTIMESTAMP,
  UPDATED_AT  TIMESTAMP     DEFAULT SYSTIMESTAMP,
  CONSTRAINT PK_PLG_PROCESSES PRIMARY KEY (ID),
  CONSTRAINT UQ_PLG_PROC_CODE UNIQUE (CODE),
  CONSTRAINT CHK_PLG_PROC_STATUS CHECK (STATUS IN ('active','draft','archived'))
);
/

CREATE OR REPLACE TRIGGER PLG_PROCESSES_BI
  BEFORE INSERT ON PLG_PROCESSES FOR EACH ROW
  WHEN (NEW.ID IS NULL)
BEGIN
  :NEW.ID := PLG_PROCESSES_SEQ.NEXTVAL;
END;
/

CREATE OR REPLACE TRIGGER PLG_PROCESSES_BU
  BEFORE UPDATE ON PLG_PROCESSES FOR EACH ROW
BEGIN
  :NEW.UPDATED_AT := SYSTIMESTAMP;
END;
/

-- ==================== Изменение выкладки ====================

DECLARE
  v_xml CLOB;
BEGIN
  DBMS_LOB.CREATETEMPORARY(v_xml, TRUE);
  DBMS_LOB.APPEND(v_xml, TO_CLOB(q'[<mxGraphModel dx="1100" dy="700" grid="0" gridSize="10" guides="1" tooltips="1" connect="1" arrows="1" fold="1" page="1" pageScale="1" pageWidth="1200" pageHeight="700" math="0" shadow="0"><root><mxCell id="0" /><mxCell id="1" parent="0" /><mxCell id="s1" value="Инициатива" style="ellipse;whiteSpace=wrap;html=1;fillColor=#14532d;strokeColor=#22c55e;fontColor=#dcfce7;fontSize=11;" vertex="1" parent="1"><mxGeometry x="40" y="150" width="52" height="52" as="geometry" /></mxCell><UserObject label="Анализ проходимости зоны" link="/UNA.md/orasldev/planograms#analytics" id="n1"><mxCell style="rounded=1;whiteSpace=wrap;html=1;arcSize=12;fillColor=#1e3a5f;strokeColor=#3b82f6;fontColor=#e8eef7;fontSize=12;" vertex="1" parent="1"><mxGeometry x="130" y="143" width="170" height="56" as="geometry" /></mxCell></UserObject><UserObject label="Оценка текущей выкладки" link="/UNA.md/orasldev/planograms#storemap" id="n2"><mxCell style="rounded=1;whiteSpace=wrap;html=1;arcSize=12;fillColor=#1e3a5f;strokeColor=#3b82f6;fontColor=#e8eef7;fontSize=12;" vertex="1" parent="1"><mxGeometry x="340" y="143" width="170" height="56" as="geometry" /></mxCell></UserObject><UserObject label="Зона перегружена?" link="/UNA.md/orasldev/planograms#storemap" id="g1"><mxCell style="rhombus;whiteSpace=wrap;html=1;fillColor=#3f2d0b;strokeColor=#f59e0b;fontColor=#fde68a;fontSize=11;" vertex="1" parent="1"><mxGeometry x="560" y="136" width="110" height="70" as="geometry" /></mxCell></UserObject><UserObject label="Перераспределить полочное пространство" link="/UNA.md/orasldev/planograms#storemap" id="n3"><mxCell style="rounded=1;whiteSpace=wrap;html=1;arcSize=12;fillColor=#1e3a5f;strokeColor=#3b82f6;fontColor=#e8eef7;fontSize=12;" vertex="1" parent="1"><mxGeometry x="720" y="40" width="170" height="56" as="geometry"]'));
  DBMS_LOB.APPEND(v_xml, TO_CLOB(q'[ /></mxCell></UserObject><UserObject label="Точечная замена SKU" link="/UNA.md/orasldev/planograms#products" id="n4"><mxCell style="rounded=1;whiteSpace=wrap;html=1;arcSize=12;fillColor=#1e3a5f;strokeColor=#3b82f6;fontColor=#e8eef7;fontSize=12;" vertex="1" parent="1"><mxGeometry x="720" y="250" width="170" height="56" as="geometry" /></mxCell></UserObject><UserObject label="Создать версию планограммы" link="/UNA.md/orasldev/planograms#plglist" id="n5"><mxCell style="rounded=1;whiteSpace=wrap;html=1;arcSize=12;fillColor=#1e3a5f;strokeColor=#3b82f6;fontColor=#e8eef7;fontSize=12;" vertex="1" parent="1"><mxGeometry x="940" y="143" width="170" height="56" as="geometry" /></mxCell></UserObject><UserObject label="Согласовано?" link="/UNA.md/orasldev/planograms#plglist" id="g2"><mxCell style="rhombus;whiteSpace=wrap;html=1;fillColor=#3f2d0b;strokeColor=#f59e0b;fontColor=#fde68a;fontSize=11;" vertex="1" parent="1"><mxGeometry x="940" y="300" width="110" height="70" as="geometry" /></mxCell></UserObject><UserObject label="Задача мерчандайзеру" link="/UNA.md/orasldev/planograms#tasks" id="n6"><mxCell style="rounded=1;whiteSpace=wrap;html=1;arcSize=12;fillColor=#14532d;strokeColor=#22c55e;fontColor=#e8eef7;fontSize=12;" vertex="1" parent="1"><mxGeometry x="700" y="400" width="170" height="56" as="geometry" /></mxCell></UserObject><UserObject label="Внедрение и фотоотчёт" link="/UNA.md/orasldev/planograms#docs" id="n7"><mxCell style="rounded=1;whiteSpace=wrap;html=1;arcSize=12;fillColor=#14532d;strokeColor=#22c55e;fontColor=#e8eef7;fontSize=12;" vertex="1" parent="1"><mxGeometry x="460" y="400" width="170" height="56" as="geometry" /></mxCell></UserObject><UserObject label="Готово" link="/UNA.md/orasldev/planograms#history" id="e1"><mxCell ]'));
  DBMS_LOB.APPEND(v_xml, TO_CLOB(q'[style="ellipse;whiteSpace=wrap;html=1;fillColor=#4c1414;strokeColor=#ef4444;fontColor=#fee2e2;fontSize=11;strokeWidth=3;" vertex="1" parent="1"><mxGeometry x="380" y="407" width="52" height="52" as="geometry" /></mxCell></UserObject><mxCell id="c1" value="" style="edgeStyle=orthogonalEdgeStyle;rounded=1;html=1;strokeColor=#64748b;fontColor=#94a3b8;fontSize=10;endArrow=block;endFill=1;" edge="1" parent="1" source="s1" target="n1"><mxGeometry relative="1" as="geometry" /></mxCell><mxCell id="c2" value="" style="edgeStyle=orthogonalEdgeStyle;rounded=1;html=1;strokeColor=#64748b;fontColor=#94a3b8;fontSize=10;endArrow=block;endFill=1;" edge="1" parent="1" source="n1" target="n2"><mxGeometry relative="1" as="geometry" /></mxCell><mxCell id="c3" value="" style="edgeStyle=orthogonalEdgeStyle;rounded=1;html=1;strokeColor=#64748b;fontColor=#94a3b8;fontSize=10;endArrow=block;endFill=1;" edge="1" parent="1" source="n2" target="g1"><mxGeometry relative="1" as="geometry" /></mxCell><mxCell id="c4" value="да" style="edgeStyle=orthogonalEdgeStyle;rounded=1;html=1;strokeColor=#64748b;fontColor=#94a3b8;fontSize=10;endArrow=block;endFill=1;" edge="1" parent="1" source="g1" target="n3"><mxGeometry relative="1" as="geometry" /></mxCell><mxCell id="c5" value="нет" style="edgeStyle=orthogonalEdgeStyle;rounded=1;html=1;strokeColor=#64748b;fontColor=#94a3b8;fontSize=10;endArrow=block;endFill=1;" edge="1" parent="1" source="g1" target="n4"><mxGeometry relative="1" as="geometry" /></mxCell><mxCell id="c6" value="" style="edgeStyle=orthogonalEdgeStyle;rounded=1;html=1;strokeColor=#64748b;fontColor=#94a3b8;fontSize=10;endArrow=block;endFill=1;" edge="1" parent="1" source="n3" target="n5"><mxGeometry relative="1" as="geometry" /></mxCell><mxCell id="c7" value="" ]'));
  DBMS_LOB.APPEND(v_xml, TO_CLOB(q'[style="edgeStyle=orthogonalEdgeStyle;rounded=1;html=1;strokeColor=#64748b;fontColor=#94a3b8;fontSize=10;endArrow=block;endFill=1;" edge="1" parent="1" source="n4" target="n5"><mxGeometry relative="1" as="geometry" /></mxCell><mxCell id="c8" value="" style="edgeStyle=orthogonalEdgeStyle;rounded=1;html=1;strokeColor=#64748b;fontColor=#94a3b8;fontSize=10;endArrow=block;endFill=1;" edge="1" parent="1" source="n5" target="g2"><mxGeometry relative="1" as="geometry" /></mxCell><mxCell id="c9" value="да" style="edgeStyle=orthogonalEdgeStyle;rounded=1;html=1;strokeColor=#64748b;fontColor=#94a3b8;fontSize=10;endArrow=block;endFill=1;" edge="1" parent="1" source="g2" target="n6"><mxGeometry relative="1" as="geometry" /></mxCell><mxCell id="c10" value="нет: доработка" style="edgeStyle=orthogonalEdgeStyle;rounded=1;html=1;strokeColor=#64748b;fontColor=#94a3b8;fontSize=10;endArrow=block;endFill=1;" edge="1" parent="1" source="g2" target="n1"><mxGeometry relative="1" as="geometry" /></mxCell><mxCell id="c11" value="" style="edgeStyle=orthogonalEdgeStyle;rounded=1;html=1;strokeColor=#64748b;fontColor=#94a3b8;fontSize=10;endArrow=block;endFill=1;" edge="1" parent="1" source="n6" target="n7"><mxGeometry relative="1" as="geometry" /></mxCell><mxCell id="c12" value="" style="edgeStyle=orthogonalEdgeStyle;rounded=1;html=1;strokeColor=#64748b;fontColor=#94a3b8;fontSize=10;endArrow=block;endFill=1;" edge="1" parent="1" source="n7" target="e1"><mxGeometry relative="1" as="geometry" /></mxCell></root></mxGraphModel>]'));
  -- Файл рассчитан на повторный запуск: схема перезаписывается целиком.
  -- Правки, сделанные оператором в бэк-офисе, при повторном деплое
  -- этого файла теряются — так и задумано, эталон схемы лежит в генераторе.
  DELETE FROM PLG_PROCESSES WHERE CODE = q'[planogram-change]';
  INSERT INTO PLG_PROCESSES (CODE, NAME_RU, NAME_RO, NAME_EN,
                             DESCR_RU, DESCR_RO, DESCR_EN,
                             DIAGRAM_XML, NODE_COUNT, SORT_ORDER, UPDATED_BY)
  VALUES (q'[planogram-change]', q'[Изменение выкладки]', q'[Modificarea expunerii]', q'[Layout change]',
          q'[От инициативы категорийного менеджера до внедрения новой выкладки в зале с фотоотчётом. Каждый шаг опирается на данные модуля: проходимость зоны, версии планограммы, задачи мерчандайзеру.]', q'[De la inițiativa managerului de categorie până la implementarea expunerii.]', q'[From the category manager initiative to the implemented layout.]',
          v_xml, 9, 1, 'system');
  DBMS_LOB.FREETEMPORARY(v_xml);
END;
/

