  -- этого файла теряются — так и задумано, эталон схемы лежит в генераторе.
  DELETE FROM PLG_PROCESSES WHERE CODE = q'[import-order]';
  INSERT INTO PLG_PROCESSES (CODE, NAME_RU, NAME_RO, NAME_EN,
                             DESCR_RU, DESCR_RO, DESCR_EN,
                             DIAGRAM_XML, NODE_COUNT, SORT_ORDER, UPDATED_BY)
  VALUES (q'[import-order]', q'[Заказ импорта товара]', q'[Comandă de import]', q'[Import order]',
          q'[От контракта до склада: проформа, оплата, производство, транзит, граница, растаможка, выпуск. План этапов строится автоматически, задержки считаются как факт минус план — по журналу видно, где и почему теряются дни.]', q'[De la contract până la depozit: etape, frontieră, vămuire.]', q'[From contract to warehouse: stages, border, customs clearance.]',
          v_xml, 9, 9, 'system');
  DBMS_LOB.FREETEMPORARY(v_xml);
END;
